update user_action set
user_id=#{userId},
item_id=#{itemId},
action_type=#{actionType},
extra_data=#{extraData}
where id = #{id}

mapper.select:
SELECT id, userId, itemId, actionType, extraData, actionTime AS createTime, username, title AS itemTitle FROM user_action_vo
username LIKE CONCAT('%', #{username}, '%')
AND title LIKE CONCAT('%', #{itemTitle}, '%')
AND actionType = #{actionType}
AND userId = #{userId}
ORDER BY actionTime DESC

